# -*- coding: utf-8 -*-

import sys
import os
sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))

from baserequest import BaseRequest

# ============ MT4 ORDER TYPES AND DEFINITIONS (Replaces OANDA) ============

class Units:
    """Units wrapper for MT4"""
    def __init__(self, units):
        self.value = str(units)


class PriceValue:
    """Price value wrapper for MT4"""
    def __init__(self, price):
        self.value = str(price)


class OrderType:
    """Order Types"""
    MARKET = "MARKET"
    LIMIT = "LIMIT"
    STOP = "STOP"
    STOP_LIMIT = "STOP_LIMIT"


class TimeInForce:
    """Time in Force"""
    FOK = "FOK"  # Fill or Kill
    IOC = "IOC"  # Immediate or Cancel
    GTC = "GTC"  # Good Till Cancelled
    DAY = "DAY"  # Day order


class OrderPositionFill:
    """Position Fill Types"""
    DEFAULT = "DEFAULT"
    OPEN_ONLY = "OPEN_ONLY"
    REDUCE_FIRST = "REDUCE_FIRST"
    REDUCE_ONLY = "REDUCE_ONLY"


class MarketOrderRequest(BaseRequest):
    """create a MarketOrderRequest.

    MarketOrderRequest is used to build the body for a MarketOrder.
    The body can be used to pass to the OrderCreate endpoint.
    
    NOTE: This has been adapted from OANDA to work with MT4.
    Actual order execution is handled via the MT4 file bridge.
    """

    def __init__(self,
                 instrument,
                 units,
                 priceBound=None,
                 positionFill=OrderPositionFill.DEFAULT,
                 clientExtensions=None,
                 takeProfitOnFill=None,
                 timeInForce=TimeInForce.FOK,
                 stopLossOnFill=None,
                 trailingStopLossOnFill=None,
                 tradeClientExtensions=None):
        """
        Instantiate a MarketOrderRequest.

        Parameters
        ----------

        instrument : string (required)
            the instrument to create the order for (e.g., 'EURUSD' for MT4)

        units: integer (required)
            the number of units. If positive the order results in a LONG
            order. If negative the order results in a SHORT order

        priceBound: float (optional)
            maximum slippage for market order

        positionFill: string (optional)
            position fill type

        clientExtensions: dict (optional)
            client extensions

        takeProfitOnFill: float (optional)
            take profit price

        timeInForce: string (optional)
            time in force (FOK or IOC allowed for market orders)

        stopLossOnFill: float (optional)
            stop loss price

        trailingStopLossOnFill: dict (optional)
            trailing stop configuration

        tradeClientExtensions: dict (optional)
            trade client extensions

        Example
        -------

        >>> from mt4_order_requests import MarketOrderRequest
        >>> 
        >>> # Create a market order request (for MT4)
        >>> order = MarketOrderRequest(
        ...     instrument="EURUSD",
        ...     units=10000,
        ...     stopLossOnFill=1.0900,
        ...     takeProfitOnFill=1.1000
        ... )
        >>> 
        >>> # For actual MT4 execution, use the MT4 client:
        >>> from mt4_price_provider import get_mt4_prices
        >>> mt4 = get_mt4_prices()
        >>> 
        >>> if units > 0:
        ...     result = mt4.buy(instrument, abs(units)/100000, stopLossOnFill, takeProfitOnFill)
        ... else:
        ...     result = mt4.sell(instrument, abs(units)/100000, stopLossOnFill, takeProfitOnFill)
        """
        super(MarketOrderRequest, self).__init__()

        # allowed: FOK/IOC
        if timeInForce not in [TimeInForce.FOK,
                               TimeInForce.IOC]:
            raise ValueError("timeInForce: {}".format(timeInForce))

        # by default for a MARKET order
        self._data.update({"type": OrderType.MARKET})
        self._data.update({"timeInForce": timeInForce})

        # required
        self._data.update({"instrument": instrument})
        self._data.update({"units": Units(units).value})

        # optional
        if priceBound:
            self._data.update({"priceBound": PriceValue(priceBound).value})

        if not hasattr(OrderPositionFill, positionFill):
            raise ValueError("positionFill {}".format(positionFill))

        self._data.update({"positionFill": positionFill})

        self._data.update({"clientExtensions": clientExtensions})
        self._data.update({"takeProfitOnFill": takeProfitOnFill})
        self._data.update({"stopLossOnFill": stopLossOnFill})
        self._data.update({"trailingStopLossOnFill": trailingStopLossOnFill})
        self._data.update({"tradeClientExtensions": tradeClientExtensions})

    @property
    def data(self):
        """data property.

        return the JSON body.
        """
        return dict({"order": super(MarketOrderRequest, self).data})


# ============ MT4 Order Executor (Helper) ============

class MT4MarketOrderExecutor:
    """
    Helper class to execute market orders in MT4 (replaces OANDA execution)
    """
    
    def __init__(self):
        from mt4_price_provider import get_mt4_prices
        self.mt4 = get_mt4_prices()
    
    def execute(self, order_request):
        """
        Execute a MarketOrderRequest in MT4
        
        Args:
            order_request: MarketOrderRequest instance
        
        Returns:
            dict: Execution result from MT4
        """
        data = order_request.data.get('order', {})
        instrument = data.get('instrument')
        units = int(data.get('units', 0))
        stop_loss = data.get('stopLossOnFill')
        take_profit = data.get('takeProfitOnFill')
        
        # Convert units to MT4 volume (standard lots)
        volume = abs(units) / 100000
        
        if units > 0:
            result = self.mt4.buy(instrument, volume, stop_loss, take_profit)
        else:
            result = self.mt4.sell(instrument, volume, stop_loss, take_profit)
        
        return result


# Optional: Create a function that mimics OANDA's behavior
def create_market_order(account_id, data=None):
    """
    Mimics OANDA's orderCreate function for compatibility.
    
    This is a compatibility wrapper that executes orders via MT4.
    
    Args:
        account_id: Not used (kept for compatibility)
        data: Order data from MarketOrderRequest
    
    Returns:
        Response object with status_code and json() method
    """
    from mt4_price_provider import get_mt4_prices
    
    class MockResponse:
        def __init__(self, result):
            self.status_code = 200 if result.get('success') else 500
            self._result = result
        
        def json(self):
            return self._result
    
    order_data = data.get('order', {})
    instrument = order_data.get('instrument')
    units = int(order_data.get('units', 0))
    stop_loss = order_data.get('stopLossOnFill')
    take_profit = order_data.get('takeProfitOnFill')
    
    volume = abs(units) / 100000
    mt4 = get_mt4_prices()
    
    if units > 0:
        result = mt4.buy(instrument, volume, stop_loss, take_profit)
    else:
        result = mt4.sell(instrument, volume, stop_loss, take_profit)
    
    return MockResponse(result)
